import { describe, expect, it } from 'vitest';
import fixtures from './fixtures/rentz.json';
import {
  RENTZ_CONTRACT_INFO,
  RENTZ_CONTRACTS,
  RENTZ_POINTS,
  rentzChooser,
  rentzFinishScore,
  rentzPlayerScore,
  validateRentzRound,
} from './rentz';

// Cases generated by the game (Tests/ScorekeeperFixtures.gd); the port must match all of them.
describe('Rentz matches the game', () => {
  it('uses the game\'s point values', () => {
    const values = fixtures.pointValues;
    expect(RENTZ_POINTS).toEqual({
      trick: values.trick,
      queen: values.queen,
      diamond: values.diamond,
      kingOfHearts: values.king_of_hearts,
      rentzBase: values.rentz_base_score,
    });
  });
  it.each(fixtures.contracts)('contract $index is $name ($short, sign $sign)', (c) => {
    const info = RENTZ_CONTRACT_INFO[RENTZ_CONTRACTS[c.index]];
    expect(info).toEqual({ name: c.name, short: c.short, sign: c.sign });
  });
  it('scores every contract from counts like the game scores the captured cards', () => {
    for (const c of fixtures.playerScores) {
      const contract = RENTZ_CONTRACTS[c.contract];
      expect(rentzPlayerScore(contract, c.counts, 4), `${contract} ${JSON.stringify(c.counts)}`).toBe(c.score);
    }
  });
  it.each(fixtures.finishScores)('Rentz place $place of $players', (c) => {
    expect(rentzFinishScore(c.place, c.players)).toBe(c.score);
    expect(rentzPlayerScore('rentz', { place: c.place }, c.players)).toBe(c.score);
  });
});

describe('Rentz round entry', () => {
  it('rotates the contract chooser', () => {
    expect([0, 1, 2, 3, 4].map((round) => rentzChooser(round, 4))).toEqual([0, 1, 2, 3, 0]);
  });
  it('checks totals for each contract', () => {
    expect(validateRentzRound('big-bids', [{ tricks: 3 }, { tricks: 3 }, { tricks: 1 }, { tricks: 1 }])).toEqual([]);
    expect(validateRentzRound('queens', [{ queens: 2 }, { queens: 1 }, { queens: 0 }, { queens: 0 }])).toEqual([
      { kind: 'total', field: 'queens', expected: 4, actual: 3 },
    ]);
    expect(validateRentzRound('diamonds', [{ diamonds: 4 }, { diamonds: 4 }, { diamonds: 0 }, { diamonds: 0 }])).toEqual([]);
    expect(
      validateRentzRound('king-of-hearts', [{ kingOfHearts: 1 }, { kingOfHearts: 1 }, { kingOfHearts: 0 }, { kingOfHearts: 0 }]),
    ).toEqual([{ kind: 'king-of-hearts-count', actual: 2 }]);
    expect(validateRentzRound('rentz', [{ place: 1 }, { place: 1 }, { place: 3 }, { place: 4 }])).toEqual([
      { kind: 'places', detail: 'duplicate' },
    ]);
  });
});
